{
  "root_causes": [
    {
      "service": "profile",
      "fault_kind": "pod_failure",
      "evidence": [
        {"kind": "metric", "sql": "SELECT time, metric, attr_k8s_pod_name pod, round(value,1) v FROM abnormal_metrics WHERE attr_k8s_pod_name = 'profile-df4d576b5-hz867' AND metric = 'k8s.container.restarts' ORDER BY time", "claim": "The profile pod's container restart counter climbed from 3 to 6 between 22:41 and 22:46, then stopped."},
        {"kind": "trace", "sql": "SELECT 'profile_spans_normal' p, count(*) n, min(time) t0, max(time) t1 FROM normal_traces WHERE service_name='profile' UNION ALL SELECT 'profile_spans_abnormal', count(*), min(time), max(time) FROM abnormal_traces WHERE service_name='profile'", "claim": "Profile emitted 1486 spans until 22:40:36 in the normal period and none in the abnormal period."},
        {"kind": "trace", "sql": "SELECT span_name, attr_status_code, count(*) n, min(time) t0, max(time) t1 FROM abnormal_traces WHERE service_name='frontend' AND span_name='profile.Profile/GetProfiles' GROUP BY 1,2 ORDER BY 2", "claim": "Frontend's calls to profile.GetProfiles returned Error 2192 times from 22:41:39 to 22:46:38, then stopped."}
      ]
    }
  ],
  "propagation": [
    {"from": "profile", "to": "frontend",
     "evidence": [
       {"kind": "trace", "sql": "SELECT span_name, attr_status_code, count(*) n, round(quantile_cont(duration,0.5)/1e6,1) med_ms FROM abnormal_traces WHERE service_name='frontend' AND attr_span_kind='Client' AND span_name='profile.Profile/GetProfiles' GROUP BY 1,2", "claim": "Frontend's profile.GetProfiles client calls fail with Error status at about 0 ms median, so they fail immediately without a response."},
       {"kind": "log", "sql": "SELECT level, message, count(*) n FROM abnormal_logs WHERE service_name='frontend' AND level='ERROR' GROUP BY 1,2", "claim": "Frontend logged 181 'Get profiles failed' errors during the incident, versus none in the normal period."}
     ]}
  ]
}
```

